command:
size_by_extension() {
  dir="$1"
  ext="$2"
  size=$(find "$dir" -type f -name "*.$ext" -printf "%s" | awk '{total+=$1} END {print total}')
  printf "%.3f MB\n" $(echo "scale=3; $size/1024/1024" | bc)
}

expected:
total_size() {
  local dir="$1"
  local ext="$2"
  local bytes=$(find "$dir" -type f -name "*.$ext" -printf "%s\n" | awk '{total+=$1} END {print total}')
  printf "Total size: %.3f MB\n" "$(echo "scale=6; $bytes/1024/1024" | bc)"
}

command:
git_rebase_test() {
  local branch="$1"
  git checkout "$branch" && git rebase master && \
    make test && git push -u origin "$branch" && echo "Rebased and pushed $branch" || {
    git rebase --abort
    git checkout "$branch"
    echo "Rebase failed, aborting"
  }
}

size_of_files(){
  dir="$1"
  ext="$2"
  find "$dir" -type f -name "*.$ext" -exec du -sm {} + | awk '{total+=$1} END {print "Total size: " total " MB"}'
}

expected:
total_size() {
  local dir="$1"
  local ext="$2"
  local bytes=$(find "$dir" -type f -name "*.$ext" -printf "%s\n" | awk '{total+=$1} END {print total}')
  printf "Total size: %.3f MB\n" "$(echo "scale=6; $bytes/1024/1024" | bc)"
}

command:
git_rebase_test() {
  local branch="$1"
  git checkout "$branch" && git rebase master && \
    if ./run_tests.sh; then git push origin "$branch"; else git rebase --abort; git checkout "$branch"; fi
}

while read -r url; do
  for i in {1..3}; do
    if curl -m 10 --retry-delay 5 --retry 3 -sSL "$url" -o "$(basename "$url")" && sha256sum "$(basename "$url")" | awk '{print "'"$url"' "$1"}' >> checksums.txt; then break; fi;
  done;
done < urls.txt

size_of_files(){
  dir="$1"
  ext="$2"
  size=$(find "$dir" -type f -name "*.$ext" -exec du -sm {} + | awk '{s+=$1} END {print s}')
  printf "%.3f MB\n" "$size"
}

expected:
total_size() {
  local dir="$1"
  local ext="$2"
  local bytes=$(find "$dir" -type f -name "*.$ext" -printf "%s\n" | awk '{total+=$1} END {print total}')
  printf "Total size: %.3f MB\n" "$(echo "scale=6; $bytes/1024/1024" | bc)"
}

command:
git_rebase_test() {
  local branch="$1"
  git checkout "$branch" && git rebase master && git push origin "$branch" || {
    git rebase --abort && git checkout "$branch"
    echo "Rebase failed, aborting"
  }
}

while read -r url; do
  for i in {1..3}; do
    if curl -m 10 --retry 0 --retry-delay 0 --retry-connrefused --retry-all-errors --retry-keep-alive --retry-protocol=retry -sSL "$url" -o "$(basename "$url")" -w "%{http_code}" -o /dev/null; then
      sha256sum "$(basename "$url")" | awk '{print \"$url\\t$1\"}' >> checksums.txt;
      break;
    fi;
  done;
done < urls

size_of_type(){
  dir="$1"
  ext="$2"
  total=$(find "$dir" -type f -name "*.$ext" -exec du -sm {} + | awk '{s+=$1} END {print s}')
  printf "%.3f MB\n" "$total"
}

expected:
total_size() {
  local dir="$1"
  local ext="$2"
  local bytes=$(find "$dir" -type f -name "*.$ext" -printf "%s\n" | awk '{total+=$1} END {print total}')
  printf "Total size: %.3f MB\n" "$(echo "scale=6; $bytes/1024/1024" | bc)"
}

command:
git_rebase_master() {
  local branch="$1"
  git checkout "$branch" && git rebase master && if git diff --quiet; then git push origin "$branch"; else git rebase --abort; git checkout "$branch"; fi
}

while read -r url; do
  for i in {1..3}; do
    if curl -m 10 -L "$url" -o "/tmp/$(basename "$url")"; then
      sha256sum "/tmp/$(basename "$url")" | awk '{print \"$url\" \"\$1\"}' >> checksums.txt;
      rm -f "/tmp/$(basename "$url")";
      break;
    fi;
  done;
done < urls.txt
